let recPage=1,recEpoch=0,recTimer;
function recForm(parent,fields,button,base){const f=monthlyNode('form');f.className='toolbar';for(const [name,label,choices] of fields){const l=monthlyNode('label',label),e=monthlyNode(choices?'select':'input');e.name=name;e.required=true;e.maxLength=500;if(choices)for(const [k,v] of choices)e.append(new Option(v,k));l.append(e);f.append(l)}const b=monthlyNode('button',button);f.append(b);parent.append(f);f.onsubmit=async e=>{e.preventDefault();const t=token;if(!t||!confirm('Enregistrer définitivement cette décision ou demande ?'))return;b.disabled=true;try{await api('billing/reconciliation','POST',{...base,...Object.fromEntries(new FormData(f))});if(t===token)await loadReconciliation()}catch(error){if(t===token)recStatus.textContent=error.message}finally{b.disabled=false}}}
async function loadReconciliation(){const t=token,id=++recEpoch;recPrev.disabled=recNext.disabled=true;try{const d=await api('billing/reconciliation?'+new URLSearchParams({q:recSearch.value,page:recPage}));if(!t||t!==token||id!==recEpoch)return;recRows.replaceChildren();for(const x of d.items){const a=monthlyNode('article');a.append(monthlyNode('h3',x.reference),monthlyNode('p','Commission : '+x.commission_amount+' '+x.commission_currency+' · '+x.commission_date+' | Dépense : '+x.expense_amount+' '+x.expense_currency+' · '+x.expense_date),monthlyNode('p','Opportunité commission : '+x.opportunity_id+' · Mission dépense : '+(x.expense_mission||'Sans mission')+' · Opportunité dépense : '+(x.expense_opportunity||'—')),monthlyNode('p',x.treatment?'Traitement approuvé : '+x.treatment:'Écart non résolu'));const details=monthlyNode('details');details.append(monthlyNode('summary','Historique et actions'));for(const h of x.history){details.append(monthlyNode('p',h.created_at+' · '+h.actor+' · '+h.treatment+' · '+h.reason+' · Pièce : '+h.evidence+' · '+(h.decision||'En attente')+(h.current?'':' · Source modifiée')+(h.reviewer?' · '+h.reviewer+' · '+h.decided_at+' · '+h.decision_reason:'')));if(h.can_decide)recForm(details,[['decision','Décision',[['APPROUVE','Approuver'],['REJETE','Rejeter']]],['reason','Motif de validation']], 'Enregistrer la décision',{request_id:h.id})}if(x.can_propose)recForm(details,[['treatment','Traitement',[['DISTINCTS','Mouvements distincts'],['DOUBLON','Doublon — dépense de référence']]],['reason','Justification'],['evidence','Référence justificative']], 'Proposer le traitement',{reference:x.reference,fingerprint:x.fingerprint});a.append(details);recRows.append(a)}recStatus.textContent=d.total+' écart(s) · Page '+d.page;recPrev.disabled=d.page===1;recNext.disabled=d.page*10>=d.total}catch(error){if(t===token&&id===recEpoch)recStatus.textContent=error.message}}
recSearch.oninput=()=>{clearTimeout(recTimer);recEpoch++;recPage=1;recTimer=setTimeout(()=>{if(token)loadReconciliation()},200)};recPrev.onclick=()=>{if(token&&recPage>1){recPage--;loadReconciliation()}};recNext.onclick=()=>{if(token&&!recNext.disabled){recPage++;loadReconciliation()}};
